<script setup lang="ts">
import {inject,onMounted,ref} from 'vue';
import {Users,UserRound,ShieldCheck,Plus,Save,KeyRound} from '@lucide/vue';
import {api} from '../../lib/api';
import type {Role} from '../../../shared/types';
import {adminSessionKey,displayDate,messageOf} from './helpers';
import AdminState from './AdminState.vue';
import AdminModal from './AdminModal.vue';
type AdminUser={id:string;authUserId:string;email?:string;role:Role;createdAt:string;active?:boolean};
const session=inject(adminSessionKey)!;
const users=ref<AdminUser[]>([]),loading=ref(true),error=ref(''),success=ref(''),open=ref(false),busy=ref(false),uid=ref(''),role=ref<Role>('reviewer'),active=ref(true),modalError=ref('');
async function load(){const result=await api<{users:AdminUser[]}>('/api/admin/users');users.value=result.users;}
function edit(user?:AdminUser){uid.value=user?.authUserId||'';role.value=user?.role||'reviewer';active.value=user?.active!==false;modalError.value='';open.value=true;}
async function save(){busy.value=true;modalError.value='';try{await api('/api/admin/users',{method:'POST',body:JSON.stringify({authUserId:uid.value.trim(),role:role.value,active:active.value})});await load();open.value=false;success.value='הרשאת החשבון נשמרה. תוקף ההרשאה נבדק בכל בקשה לשרת.';}catch(e){modalError.value=messageOf(e);}finally{busy.value=false;}}
onMounted(()=>{if(session.role!=='administrator'){loading.value=false;return;}void load().catch(e=>{error.value=messageOf(e);}).finally(()=>{loading.value=false;});});
</script>
<template><div v-if="session.role!=='administrator'" class="admin-panel"><AdminState title="הגישה מוגבלת למנהלי מערכת" description="ניהול חשבונות והרשאות זמין למנהלי מערכת בלבד."/></div><template v-else><div class="admin-page-heading"><div><span class="admin-eyebrow">הצוות של הארגון</span><h1>משתמשים והרשאות</h1><p>גישה לצוות מורשה, בהתאם לתחומי האחריות.</p></div><button class="btn btn-primary" @click="edit()"><Plus :size="17"/>הענקת הרשאה</button></div><div v-if="error" class="admin-error" role="alert">{{error}}</div><div v-if="success" class="admin-success" role="status">{{success}}</div><div class="admin-role-grid"><div><span class="stat-icon stat-icon-blue"><ShieldCheck :size="23"/></span><div><h2>מנהל מערכת</h2><p>ניהול דיווחים, חברות, הרשאות ובקשות פרטיות. ייצוא מפורט עם פרטים אישיים.</p></div></div><div><span class="stat-icon stat-icon-teal"><UserRound :size="23"/></span><div><h2>בודק דיווחים</h2><p>צפייה בדיווחים ובמסמכים, תיעוד ושינוי סטטוס. ייצוא סטטיסטי ללא פרטים מזהים.</p></div></div></div><section class="admin-panel"><header class="admin-panel-header"><h2><Users :size="20"/>הצוות המורשה</h2><span class="admin-count">{{users.length}}</span></header><AdminState v-if="loading" loading/><div v-else-if="users.length" class="table-wrap"><table class="data-table"><thead><tr><th>משתמש</th><th>מזהה Firebase Auth</th><th>תפקיד</th><th>גישה</th><th>נוצר בתאריך</th><th>פעולות</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><span class="admin-user-table"><span class="admin-user-avatar">{{(user.email||'U').charAt(0).toUpperCase()}}</span><span dir="auto">{{user.email||'חשבון מורשה'}}<small v-if="user.id===session.id||user.authUserId===session.id">החשבון שלך</small></span></span></td><td><code class="admin-uuid">{{user.authUserId}}</code></td><td><span :class="['status-badge',user.role==='administrator'?'status-purple':'status-blue']">{{user.role==='administrator'?'מנהל מערכת':'בודק דיווחים'}}</span></td><td>{{user.active===false?'מושבתת':'פעילה'}}</td><td>{{displayDate(user.createdAt)}}</td><td><button class="btn btn-ghost" @click="edit(user)">עריכת הרשאה</button></td></tr></tbody></table></div><AdminState v-else title="אין משתמשים להצגה"/></section><div class="admin-workspace-note"><KeyRound :size="23"/><div><strong>אימות והרשאה נבדקים בנפרד</strong><span>צרו חשבון מאומת ב־Firebase Authentication, והעניקו לו תפקיד כאן. בשרת החי נדרש גם אימות TOTP דו־שלבי.</span></div></div>
<AdminModal v-if="open" title="הרשאה לחשבון Firebase קיים" :busy="busy" @close="!busy&&(open=false)"><form @submit.prevent="save"><div class="admin-modal-body"><div v-if="modalError" class="admin-error" role="alert">{{modalError}}</div><p class="admin-field-hint">פעולה זו מעניקה או מעדכנת תפקיד לחשבון קיים. היא אינה יוצרת חשבון Firebase חדש.</p><label class="field"><span class="field-label">מזהה משתמש · Firebase Auth UID</span><input v-model="uid" class="input" dir="ltr" required minlength="1" maxlength="128" autocomplete="off"/></label><label class="field"><span class="field-label">תפקיד במערכת</span><select v-model="role" class="select"><option value="reviewer">בודק דיווחים</option><option value="administrator">מנהל מערכת</option></select></label><label class="admin-checkbox"><input v-model="active" type="checkbox"/>גישה פעילה למערכת</label><div class="admin-info">שינוי תפקיד מתועד ביומן הניהול. השרת מגן על הרשאת מנהל המערכת האחרון.</div></div><div class="admin-modal-footer"><button class="btn btn-secondary" type="button" :disabled="busy" @click="open=false">ביטול</button><button class="btn btn-primary" :disabled="busy"><Save :size="16"/>שמירת הרשאה</button></div></form></AdminModal></template></template>
